// План specs/admin-coupons.md 2.7 (кейс CP-11). Пользователь «בדיקה» wojeg27104 (auth/user.json), десктоп, EN.
// @prod-safe: только Check (проверка кода), «Continue to payment» не нажимается; запись/погашение и checkout.stripe.com обрываются.
// Состояние купонов на 19.10: все Disabled. Поэтому «belongs to another account» и «has expired» на живых купонах сейчас
// не воспроизводятся (оба купона отключены) — ручной кейс CP-14; здесь — фактические ответы для отключённых купонов.
import { test, expect } from '../../fixtures';
import { CHECK_ERRORS, COUPONS, blockCouponWrites, checkCoupon, expectNoCouponWrites, startUserEn } from './coupon-helpers';

const ALL_ERRORS = Object.values(CHECK_ERRORS);

test.describe('Billing coupon Check: errors (#a10206 #b93722)', () => {
  const cases: { title: string; code: () => string; expected: string[] }[] = [
    { title: 'unknown code → "This coupon code does not exist."', code: () => `QA-AUTO-NOPE-${Date.now().toString(36).toUpperCase()}`, expected: [CHECK_ERRORS.notFound] },
    { title: 'disabled own coupon QA-PCT10-1410 → "This coupon is no longer active."', code: () => COUPONS.pct10, expected: [CHECK_ERRORS.inactive] },
    // Чужой купон (только iamdejar) после Disable — «no longer active» (указание сессии 19.10); «belongs to another account» — только для активного чужого.
    { title: 'disabled coupon of another account QA-R1-ONLY-1910 → "This coupon is no longer active."', code: () => COUPONS.onlyOther, expected: [CHECK_ERRORS.inactive] },
    // Истёкший и затем отключённый: на 18.10 (только истёк) — «has expired»; после Disable порядок проверок не сверен → допускаем одно из двух.
    { title: 'expired then disabled QA-EXP2-1810 → "This coupon has expired." or "This coupon is no longer active."', code: () => COUPONS.exp2, expected: [CHECK_ERRORS.expired, CHECK_ERRORS.inactive] },
  ];

  for (const c of cases) {
    test(`Billing coupon Check: ${c.title}, no price and no "Continue to payment" #a10206 #b93722 @desktop @prod-safe`, async ({ asUser }) => {
      const page = await asUser('user');
      await startUserEn(page);
      const writes = await blockCouponWrites(page);
      // Источник: ticket #291f7a9d/#a10206 — проверка при погашении; тексты — ручная проверка 19.10 (r1-s5-*.png).
      await checkCoupon(page, c.code());
      const shown = page.getByText(new RegExp(`^(${ALL_ERRORS.map((e) => e.replace(/\./g, '\\.')).join('|')})$`));
      await expect(shown).toBeVisible();
      expect(c.expected, 'текст ошибки').toContain((await shown.innerText()).trim());
      await expect(page.getByRole('button', { name: 'Continue to payment' })).toHaveCount(0);
      expectNoCouponWrites(writes);
    });
  }
});
